// Provide functions for extensions and includes

// The main functions are the following, the first three are called on-demand in
// the "origin chain loop", i.e. in dependency order:
//
// extendArtifactBefore(), called at the start of the loop body:
//  - traverses collected extensions for the given artifact, and for each property,
//    select one (or sort them, e.g. for `includes`) if multiple extensions exist
//  - _also called_ by main function of this file for all user-defined main artifacts,
//    because we need some annotations rather early → the "origin" is not necessarily
//    processed → this fn can't inspect the "origin" or derived props of includes
//
// … in between: populateGeneratedEntity(), resolveInclude(), populateArtifact()
//
// extendArtifactAdd(), called in the middle of the loop body:
//  - add elements, enums and actions to artifact via includes and/or extension
//
// … in between: set _effectiveType, mergeSpecifiedElementsOrEnum(), generateForEntity()
//
// extendArtifactAfter(), called at the end of the loop body:
//  - pushes down member extensions to members
//  - handles type property extensions (TODO: move to extendArtifactAdd)
//
// createRemainingAnnotateStatements(), called near end of compilation
//  - creates `annotate` statements for non-applied extensions

// Sections in this file: -------------------------------------------------------
//  - Pushdown and transform extensions
//  - Sort sources, select/sort extension
//  - Array annotations with `...`, same anno values
//  - Special properties: query clauses, type properties
//  - Add new members
//  - Create “super” ANNOTATE statements
//  - TODO TMP: initMembers()
//  - TODO TMP: includes
//  - Foreign key extensions (currently postponed)
//  - Utility functions

'use strict';

const { weakRefLocation } = require('../base/location');
const {
  dictAdd,
  pushToDict,
  dictNonEmpty,
  dictFirst,
} = require('./dictionaries');
const { kindProperties } = require('./base');
const {
  setLink,
  setArtifactLink,
  copyExpr,
  setExpandStatus,
  linkToOrigin,
  initItemsLinks,
  outerArtifact,
  createAndLinkCalcDepElement,
  initBoundSelfParam,
  dependsOnSilent,
  hasSecurityAnno,
  extensionRefContext,
  pathName,
  annotationHasEllipsis,
  forEachInOrder,
  forEachDefinition,
  forEachMember,
  forEachGeneric,
} = require('./utils');
const layers = require('./moduleLayers');
const { CompilerAssertion } = require('../base/error');
const { Location } = require('../base/location');
const { typeParameters } = require('./builtins');
const { XsnArtifact, XsnName } = require('./xsn-model');

const $location = Symbol.for( 'cds.$location' );
const $inferred = Symbol.for( 'cds.$inferred' ); // TODO: no $inferred yet?

// attach stupid location - TODO: remove in v7
const genLocation = new Location( '' );

const draftElements = [
  'IsActiveEntity',
  'HasActiveEntity',
  'HasDraftEntity',
  'DraftAdministrativeData',
  'SiblingEntity',
];
const draftBoundActions = [
  'draftPrepare',
  'draftActivate',
  'draftEdit',
];

function extend( model ) {
  // Get simplified "resolve" functionality and the message function:
  const {
    message, error, warning, info,
  } = model.$messageFunctions;
  const {
    resolvePath,
    resolveUncheckedPath,
    resolveTypeArgumentsUnchecked,
    resolveDefinitionName,
    attachAndEmitValidNames,
  } = model.$functions;

  Object.assign( model.$functions, {
    createRemainingAnnotateStatements,
    extendArtifactBefore,
    extendArtifactAfter,
    extendArtifactAdd,
    extendForeignKeys,
    withLocalizedData,
  } );

  sortModelSources();
  // Set annotations on user-provided artifacts, but they are not propagated yet!
  forEachDefinition( model, extendArtifactBefore );
  return;


  // Pushdown and transform extensions ------------------------------------------

  /**
   * Push down extensions on member properties like `elements` to the individual
   * members (setting their `_extensions` property).
   * Currently, definitions in `extend` members are ignored,
   * because they are handled a-priori by the old-style extension mechanism.
   *
   * Outside this file: only called in effectiveType() and indirectly in
   * tweak-assocs.js (for foreign keys and super-annotates).
   */
  function extendArtifactAfter( art ) {
    // TODO: assert that we have not yet transformed/used _extensions on sub elements
    // TODO necessary(?): transformArtifactExtensions must ensure that each annotate
    // is in either returns,items,elements,enum
    if (art.builtin)            // builtin members handled via "super annotate"
      return;
    // If elements are added in the future via includes or extend, it should be done here

    const extensionsMap = art._extensions;
    if (!extensionsMap)         // builtin members handled via "super annotate"
      return;
    // type extensions after having “populated” the artifact ($typeArgs -> length,
    // …, TODO: do that there) and setting an _effectiveType:
    if (art.$typeExts) {
      const { type } = art;     // if the type is not inferred, it is the origin...
      if (type?._artifact && !type.$inferred) // ...and thus is resolved
        resolveTypeArgumentsUnchecked( art, type._artifact, art );
      const exts = art.$typeExts;
      applyTypeExtensions( art, exts.length, 'length' );
      const scaleDiff = applyTypeExtensions( art, exts.scale, 'scale' );
      applyTypeExtensions( art, exts.precision, 'precision', scaleDiff );
      applyTypeExtensions( art, exts.srid, 'srid' );
      checkPrecisionScaleExtension( art, exts );

      delete art.$typeExts;
    }

    moveDictExtensions( art, extensionsMap, 'actions' );
    moveDictExtensions( art, extensionsMap, 'params' );
    if (!extensionsMap.elements)
      return;

    // after populateArtifact, it is clear which properties the artifact has:
    const artProp = art.kind === 'action' || art.kind === 'function'
      ? 'returns'
      : [ 'returns', 'targetAspect', 'items' ].find( p => art[p] );
    if (artProp) {
      const returnsDict = artProp === 'returns' && !art.returns &&
        annotateFor( art, 'params', '' );  // create anno for non-existing returns
      for (const ext of extensionsMap.elements) {
        if (!ext.returns) {
          if (artProp === 'returns') {
            reportMissingReturns( ext, art );
            if (ext.kind === 'extend')
              continue;
          }
          pushToDict( returnsDict || art[artProp], '_extensions', ext );
        }
        else {
          pushToDict( returnsDict || art[artProp], '_extensions', ext.returns );
          if (!art.returns)
            reportUnexpectedReturns( ext, art );
        }
      }
      // TODO: what about `many many Type` (via CSN)?
    }
    else if (!art.target) { // TODO: foreign keys currently handled specially
      for (const ext of extensionsMap.elements) {
        if (ext.returns)
          reportUnexpectedReturns( ext, art ); // TODO: ???
      }
      // if (art.elements || art.enum || art.kind === 'annotate')
      moveDictExtensions( art, extensionsMap,
                          (art.enum ? 'enum' : 'elements'), false );
    }
  }

  function moveDictExtensions( art, extensionsMap, artProp, extProp = artProp ) {
    const extensions = extensionsMap[extProp || 'elements'];
    if (!extensions)
      return;
    for (const ext of extensions) {
      const members = art[artProp];
      const realExtProp = extProp || (ext.enum ? 'enum' : 'elements');
      if (!members && !checkExtensionDictionary( ext, art, artProp, realExtProp ))
        continue;
      forEachGeneric( ext, realExtProp, ( elemExt, name ) => {
        if (elemExt.kind !== 'annotate' && elemExt.kind !== 'extend')
          return;             // definitions inside extend, already handled
        // Remark: don't test elemExt.$duplicates, `annotate A (@Foo P, @Bar P)` should work
        reportUnexpectedMemberExtensions( art, elemExt, artProp, name );
        const elem = members?.[name] || annotateFor( art, extProp || 'elements', name );
        setLink( elemExt.name, '_artifact', (elem.kind !== 'annotate' ? elem : null ) );
        // null, because the element is not really there, just in a "super annotate"
        if (elem.$duplicates !== true) // TODO: re-check, or just !elem.$duplicates
          pushToDict( elem, '_extensions', elemExt );
      });
    }
  }

  /**
   * Transform `art._extensions` from an array of extensions into an object
   * `{ prop: relevantExtensions, … }` where `relevantExtensions` are the extensions
   * which are relevant for the value of `art[prop]` after the application of extensions.
   *
   * A special property is `$add`: it collects extensions for both `elements` (+
   * `enum`) extensions and `includes` (also without elements, because the order
   * of includes might influences which inludes wins for inherited annotations).
   *
   * Called in extendArtifactBefore(), where it is not necessarily clear whether
   * `art` has `elements`, `enums`, `items`, etc.
   */
  function transformArtifactExtensions( art ) {
    // TODO: if extensions has more than one of returns,items,elements,enum, delete all those props
    const dict = {};
    for (const ext of art._extensions) {
      // `annotate SomeFunction with @action { r @elem };` would later be moved to
      // `someFunction.returns._extensions` due to `elements` → @action not relevant then:
      // (TODO: should we use some “already applied” flag instead?)
      const isAutoItemsOrReturns = art._outer || // in items or targetAspect
        art._parent?.returns === art && !ext._parent?.returns;
      for (const prop in ext) {
        if (!Object.hasOwn( ext, prop ) || ext[prop] === undefined) // deleted property
          continue;
        // TODO: do this check nicer (after complete move to new extensions mechanism)
        if (prop === 'includes') {
          pushToDict( dict, prop, ext );
          pushTo$add( dict, ext );
        }
        else if (prop.charAt(0) === '@' || prop === 'doc' || prop === 'columns' ||
                 prop === 'groupBy' || prop === 'where' || prop === 'having' ||
                 prop === 'orderBy' || prop === 'limit' || prop === 'length' ||
                 prop === 'scale' || prop === 'precision' || prop === 'srid') {
          if (!isAutoItemsOrReturns) // these props are ignored inside items/returns
            pushToDict( dict, prop, ext );
        }
        else if (prop === 'elements' || prop === 'enum') {
          if (ext.returns) {                    // TODO: currently, an annotate can have both
            // if this is a hard error, we could use syntax-unexpected-property#sibling
            message( 'syntax-unexpected-with-returns',
                     [ ext[prop][$location] || ext.location, ext ],
                     { prop, siblingprop: 'returns' },
                     // eslint-disable-next-line @stylistic/max-len
                     'Property $(PROP) of an annotate statement is ignored when it also has a property $(SIBLINGPROP)' );
          }
          else {
            pushToDict( dict, 'elements', ext ); // yes, enum → elements here
            // if at least one elem/enum (TODO):
            // && Object.keys( ext.elements ).some( elem => elem.kind !== 'extend' ))
            // Add to $add if not already for includes:
            if (ext.kind === 'extend' && !ext.includes)
              pushTo$add( dict, ext );
            // TODO: issue error for ext on art having returns/items if ext has both
            // include/actions/params and elements/enum (or handle that properly)
          }
        }
        else if (prop === 'returns') {
          pushToDict( dict, 'elements', ext );
          if (hasSecurityAnno( ext.returns ))
            reportUnexpectedReturns( ext, ext );
          // create 'returns' for the super annotate, store in elements anyway
          if (!art.returns && art.kind === 'annotate')
            annotateCreate( art, '', art, 'returns' );
          if (ext.kind === 'extend' && !isAutoItemsOrReturns)
            pushTo$add( dict, ext );
        }
        else if (prop === 'actions' || prop === 'params') {
          pushToDict( dict, prop, ext );
        }
      }
    }
    art._extensions = dict;
  }

  // Sort sources, select/sort extensions ---------------------------------------

  /**
   * Sort sources according to the reversed layered extension order without
   * reporting any messages.
   *
   * The order of the CSN property `$sources` (from XSN `_sortedSources`) is
   * defined as follows: for _any_ model
   *
   *  - add `type $Sources: String @(Names: []);` to one of the source files
   *  - add `annotate $Sources with @Names: [..., ‹sourceName›]` to each source
   *    file where ‹sourceName› is the file name of the source
   *  - then the array value of `‹csn›.$sources` is the reverse of the array value
   *    of `‹csn›.definitions.$Sources.@Names`
   */
  function sortModelSources() {
    const scheduled = [];
    const layered = layeredExtensions( Object.values( model.sources ) );
    for (;;) {
      const { highest } = extensionsOfHighestLayers( layered );
      if (!highest.length)
        break;
      highest.reverse();
      scheduled.push( ...highest );
    }
    setLink( model, '_sortedSources', scheduled );
  }

  /**
   * Traverses collected extensions for the given artifact, and for each property,
   * select one (or sort them, e.g. for `includes`) if multiple extensions exist.
   *
   * Consider the module layer for the selection/sorting, and issue messages.
   *
   * Called at the beginning for each main artifact, and must not call
   * resolvePath() then.
   *
   * @param {XSN.Artifact} art
   */
  function extendArtifactBefore( art ) {
    // for main artifacts, move extensions from `$collectedExtensions` model dictionary:
    if (!art._main && !art._outer && art._extensions === undefined &&
        art.name && // TODO: probably just a workaround, check with TODO in getOriginRaw()
        art.kind !== 'namespace') {
      const { id } = art.name;
      setLink( art, '_extensions', model.$collectedExtensions[id]?._extensions || null );
      if (art._extensions && !art.builtin) { // keep extensions for builtin in $collectedExtensions
        delete model.$collectedExtensions[id];
        // TODO: if the extension mechanism has been completed, we could uncomment:
        // art._extensions.forEach( ext => resolvePath( ext.name, ext.kind, ext )); // for LSP
        // for now, we do that at the end of createRemainingAnnotateStatements()
      }
    }
    if (art.kind === 'entity' && art.includes && !art._entityIncludes)
      setEntityIncludes( art, art );

    if (Array.isArray( art._extensions )) {
      // TODO: the following function can now be simplified
      // if (art.$inferred) console.log('CAI:', art.name, art.$inferred,art._extensions)
      // With extensions, member appears in CSN, affects directly the rendering of
      // elements etc.  TODO: do that more specifically on the dicts (via symbol)
      // Probably better: we could use the _extensions dict prop directly in to-csn
      if (art.$inferred)
        setExpandStatus( art, 'annotate' );
      if (Array.isArray( art._extensions )) {
        reportInvalidExtensionKind( art._extensions, art );
        transformArtifactExtensions( art );
      }
      // console.log('EA:',require('../model/revealInternalProperties')
      //             .ref(art),Object.keys(art._extensions))
      for (const prop in art._extensions) {
        if (Object.hasOwn( art._extensions, prop ))
          applyPropertyExtensions( art, prop );
      }
    }
  }

  /**
   * Collect all includes which are entities in property `_entityIncludes`.
   * This information is needed to kick-start the auto-redirection mechanism,
   * i.e. must be called in extendArtifactBefore().
   *
   * A consequence is that a compiler-generated entity must never include an
   * entity; the generated entity could be an auto-redirection target otherwise
   * → an on-demand generated could change the auto-redirection behavior.
   */
  function setEntityIncludes( ext, art ) {
    // TODO: better to call this once at the end of extendArtifactBefore()
    setLink( art, '_entityIncludes', [] );
    for (const ref of ext.includes) {
      const name = resolveUncheckedPath( ref, 'include', ext );
      const template = name && model.definitions[name];
      if (template?.kind === 'entity')
        art._entityIncludes.push( template );
    }
  }

  /**
   * For all `prop → extensions` in `art._extensions`, apply the extensions.
   * Currently only for annotations, the `doc` property, `columns` and type properties,
   * not for `elements` and other members.
   */
  function applyPropertyExtensions( art, prop ) {
    if (prop === 'params' || prop === 'returns' || prop === 'elements')
      return;                   // only for push-down

    const extensions = art._extensions;
    // annotations, `doc`, `includes`, `columns`, `length`, ...
    const scheduled = [];
    // sort extensions according to layer (specified elements are bottom layer):
    const layered = layeredExtensions( extensions[prop] );

    let cont = true;
    while (cont) {
      const { highest, issue } = extensionsOfHighestLayers( layered );
      // console.log( 'CA:', annoName, issue, extensions)
      let index = highest.length;
      cont = !!index;         // safety
      while (--index >= 0) {
        const ext = highest[index];
        scheduled.push( ext );
        if (extensionOverwrites( ext, prop )) {
          cont = false;
          break;
        }
      }
      if (issue || index > 0)
        reportDuplicateExtensions( highest, prop, issue, index, art );
    }
    // Now apply the relevant extensions
    scheduled.reverse();
    if (prop === 'includes' && !art.includes?.$original) {
      const $original = art.includes ?? [];
      art.includes = [ ...$original ];
      art.includes.$original = $original;
      // extensions[prop] = scheduled;
      // console.log('APE:',art.name.id,art.includes.map( r => r._artifact?.name.id ))
    }
    if (prop === '$add' || prop === 'actions') {
      extensions[prop] = scheduled;
      return;                   // $add and actions are applied in extendArtifactAdd()
    }
    for (const ext of scheduled)
      applySingleExtension( art, ext, prop );
  }

  function extensionOverwrites( ext, prop ) {
    return (prop.charAt(0) !== '@')
      ? (prop === 'doc' || typeParameters.list.includes(prop))
      : !annotationHasEllipsis( ext[prop] );
  }

  function applySingleExtension( art, ext, prop ) {
    if (prop === 'includes') {
      if (art.kind !== 'annotate' && !art._outer) { // TODO: why this check?
        // not with elem extension in targetAspect
        art.includes.push( ...ext.includes );
        // head of ref in in ext.includes must be set in _block of ext; for
        // remaining path items, effectiveType() has `art` as user
        // (alternatively, we could set some _user on `includes` items):
        for (const ref of ext.includes)
          resolveUncheckedPath( ref, 'include', ext );
        // TODO: some warning if duplicate ref
        if (art.kind === 'entity')
          setEntityIncludes( ext, art );
        // console.log( 'ASI:',prop,art.name,ext,extensionsDict[id])
      }
      // art[prop] = (art[prop]) ? art[prop].concat( ext[prop] ) : ext[prop];
    }
    else if (prop === 'columns') {
      const { query } = art;
      for (const col of ext.columns)
        col.$extended = 'columns';

      if (art.kind === 'annotate' && art.$inferred === '')
        return; // internal super-annotate for unknown artifacts

      if (!query?.from?.path) {
        const variant = (query?.from || query)?.op?.val || 'std';
        error( 'extend-columns', [ ext.columns[$location], ext ], { '#': variant, art } );
        return;
      }
      if (!query.columns) {
        query.columns = [ {
          __proto__: XsnArtifact.prototype, location: query.from.location, val: '*',
        }, ...ext.columns ];
      }
      else {
        query.columns.push( ...ext.columns );
      }
      ext.columns.forEach( col => changeParentLinks( col, query ) );
    }
    else if (prop === 'groupBy' || prop === 'where' || prop === 'having' ||
             prop === 'orderBy' || prop === 'limit') {
      applyQueryClause( prop, ext, art );
    }
    else if (typeParameters.list.includes( prop )) {
      const typeExts = art.$typeExts || (art.$typeExts = {});
      typeExts[prop] = ext;
    }
    else {
      const result = applyAssignment( art[prop], ext[prop], ext, prop );
      // Remark: result is ext[prop] if without [...]
      art[prop] = (result.name) ? result : Object.assign( {}, art[prop], result );
    }
  }

  // Array annotations with `...`: ----------------------------------------------

  function applyAssignment( previousAnno, anno, art, annoName ) {
    const firstEllipsis = annotationHasEllipsis( anno );
    if (!firstEllipsis)
      return anno;
    const hasBase = previousAnno?.literal === 'array';
    if (!previousAnno) {
      const { location } = anno.name;
      if (annoName !== '@extension.code') {
        // Remark: we could allow that for all annotations which are not propagated
        message( 'anno-unexpected-ellipsis', [ firstEllipsis.location || location, art ],
                 { code: '...' } );
      }
      previousAnno = {
        kind: '$annotation',
        val: [],
        literal: 'array',
        name: anno.name,
        location,
      };
    }
    else if (previousAnno.literal !== 'array') {
      // TODO: If we introduce sub-messages, point to the non-array base value.
      error( 'anno-mismatched-ellipsis', [ anno.name.location, art ], { code: '...' } );
      previousAnno = {
        kind: '$annotation',
        val: [],
        literal: 'array',
        name: previousAnno.name,
        location: previousAnno.location,
      };
    }
    const previousValue = previousAnno.val;
    let prevPos = 0;
    const result = [];
    for (const item of anno.val) {
      const ell = item && item.literal === 'token' && item.val === '...';
      if (!ell) {
        result.push( item );
      }
      else {
        let upToSpec = !item.$errorReported && item.upTo;
        // $errorReported: no anno-unexpected-upto-value with anno-invalid-upto-value
        while (prevPos < previousValue.length) {
          const prevItem = previousValue[prevPos++];
          result.push( prevItem );
          if (upToSpec && prevItem && equalUpTo( prevItem, item.upTo )) {
            upToSpec = false;
            break;
          }
        }
        if (upToSpec && hasBase) {
          // non-matched UP TO; if there is no base to apply to, there is already an error.
          warning( 'anno-unexpected-upto-value', [ item.upTo.location, art ],
                   { anno: annoName, code: '... up to' },
                   'The $(CODE) value does not match any item in the base annotation $(ANNO)' );
        }
      }
    }
    // console.log('TP:',previousValue.map(se),anno.val.map(se),'->',result.map(se))
    return {
      kind: '$annotation',
      val: result,
      literal: 'array',
      name: previousAnno.name,
      location: previousAnno.location,
    };
  }

  // For the `up to` specification, see ../../test3/Annotations/EllipsisUpTo/
  function equalUpTo( previousItem, upToSpec ) {
    if (!previousItem)
      return false;

    if (upToSpec.sym)           // enum symbol (literal: 'enum')
      return previousItem.sym?.id === upToSpec.sym.id;
    if (upToSpec.val !== undefined) {        // not struct, ref or non-val expression
      if (previousItem.val === upToSpec.val) // enum, struct and ref have no val
        return true;
      const upToVal = upToSpec.val;
      const prevVal = previousItem.val;
      // eslint-disable-next-line eqeqeq
      return prevVal == upToVal &&
        ( typeof upToVal === 'number' && stringCouldHaveBeenCdlNumber( prevVal ) ||
          typeof prevVal === 'number' && stringCouldHaveBeenCdlNumber( upToVal ) );
    }

    if (upToSpec.path) {
      // console.log(upToSpec.location+'',normalizeRef( upToSpec ),previousItem.struct?.['='])
      return (previousItem.path)
        ? normalizeRef( upToSpec ) === normalizeRef( previousItem )
        : normalizeRef( upToSpec ) === previousItem.struct?.['=']?.val &&
          (!upToSpec.$tokenTexts || Object.keys( previousItem.struct ).length === 1);
    }
    if (!upToSpec.struct)
      return false;

    const { struct } = previousItem;
    if (struct) {
      const entries = Object.entries( upToSpec.struct );
      // {} does not match { "=": "ref" }, but { prop: … } and { "=": "ref", more: … }
      return (entries.length)
        ? entries.every( ([ n, v ]) => equalUpTo( previousItem.struct[n], v ) )
        : !struct['='] || Object.keys( struct ).length > 1;
    }
    return previousItem.path && Object.keys( upToSpec.struct ).length === 1 &&
      normalizeRef( previousItem ) === upToSpec.struct['=']?.val;
  }

  // We only compare a string by number if the string is not empty, and could have
  // been produced for a CDL number by (a previous version of) the compiler,
  // i.e. having used a decimal dot, or using the scientific notation:
  function stringCouldHaveBeenCdlNumber( val ) { // also consider previous compiler versions
    return val && typeof val === 'string' && /[.eE]/.test( val );
    // We do not use `!Number.isSafeInteger( Number.parseFloat( text||'0' )`
    // because it is unlikely that people have written a non-integer like this,
    // more likely is meant a digit-sequence as string
  }

  function normalizeRef( node ) { // see to-csn.js
    const ref = pathName( node.path );
    // TODO XSN 7.2: get rid of name.variant (induces a wrong structure anyway)
    return node.variant ? `${ ref }#${ pathName( node.variant.path ) }` : ref;
  }

  // Special properties: query clauses, type properties -------------------------

  function applyQueryClause( prop, ext, art ) {
    const { query } = art;
    const clause = ext[prop];
    const isArray = Array.isArray( clause );

    if (prop !== 'limit') {
      const items = isArray ? clause : [ clause ];
      for (const item of items) {
        item.$extended = prop;
        setLink( item, '_block', ext._block );
        setLink( item, '_outer', query );
      }
    }
    if (!query?.from?.path) {
      const variant = (query?.from || query)?.op?.val || 'std';
      const loc = isArray ? clause[$location] : clause.location;
      error( `extend-${ prop.toLowerCase() }`, [ loc, ext ], { '#': variant, art } );
      return;
    }
    if (isArray) {
      if (!query[prop])
        query[prop] = [];
      query[prop].push( ...clause );
    }
    else if (prop === 'where' || prop === 'having') {
      const existing = query[prop];
      if (!existing) {
        query[prop] = clause;
      }
      else if (existing.op?.val === 'and' &&
               existing.args.some( a => a.$extended === prop )) {
        existing.args.push( clause );
      }
      else {
        query[prop] = {
          op: { val: 'and', location: art.name.location },
          args: [ existing, clause ],
          location: clause.location,
        };
      }
    }
    else if (query[prop]) {
      error( 'ext-unexpected-sql-clause', [ clause.location, ext ], { art, keyword: prop } );
    }
    else {
      query[prop] = clause;
    }
  }

  // Remarks on messages: we allow the type extensions only if the artifact
  // originally had that property → any check of the kind “type prop can only be
  // used with FooBar” is independent from `extend … with type`.  Function
  // checkTypeArguments() in resolve.js reports 'type-unexpected-argument', but
  // that is currently incomplete.
  //
  // We then report (in the future), use the first message of:
  // - the usual messages if a type argument is wrong, independently from `extend`
  // - 'ext-unexpected-type-argument' (TODO) if the artifact does not have the prop
  // - 'ext-invalid-type-argument' if the value is wrong for extend (no overwrite)
  //
  // TODO v8: do not allow `extend … with (precision: …)` alone if original def also has `scale`
  function applyTypeExtensions( art, ext, prop, scaleDiff ) {
    // console.log('ATE:',art?.[prop],ext?.[prop],scaleDiff)
    if (!ext?.[prop])
      return 0;
    if (!art[prop]) {
      const isBuiltin = art._effectiveType?.builtin;
      if (isBuiltin && !allowsTypeArgument( art, prop )) {
        // Let checkTypeArguments() in resolve.js report a message, is incomplete
        // though, i.e. can only safely be used for scalars at the moment.  But we
        // will improve that function and not try to do extra things here.
        art[prop] = ext[prop];  // enable checkTypeArguments() doing its job
        return 0;
      }
      // TODO: think about 'ext-unexpected-type-argument'
      error( 'ext-invalid-type-property', [ ext[prop].location, ext ],
             { '#': (isBuiltin ? 'indirect' : 'new-prop'), prop } );
      return 0;
    }
    const artVal = art[prop].val;
    const extVal = ext[prop].val;
    if (prop === 'srid') {
      error( 'ext-invalid-type-property', [ ext[prop].location, ext ], { '#': 'prop', prop } );
    }
    else if (typeof artVal !== 'number' || typeof extVal !== 'number' ) {
      // Users can't change from/to string value for property,
      // e.g. `variable`/`floating` for Decimal
      // TODO: Shouldn't the text distinguish between orig string and extension string?
      // Not sure whether to talk about strings if we have a keyword in CDL
      error( 'ext-invalid-type-property', [ ext[prop].location, ext ], { '#': 'string', prop } );
    }
    else if (extVal < artVal + (scaleDiff || 0)) {
      const number = artVal + (scaleDiff || 0);
      error( 'ext-invalid-type-property', [ ext[prop].location, ext ], {
        '#': (scaleDiff ? 'scale' : 'number'), prop, number, otherprop: 'scale',
      } );
    }
    else {
      art[prop] = ext[prop];
      return extVal - artVal;
    }
    return 0;
  }

  /**
   * If the target artifact has both precision and scale set, then extensions on it must also
   * provide both to avoid user errors for subsequent `extend` statements.
   * There is already a syntax error [syntax-missing-type-property] for `scale` without `precision`.
   *
   * @param {XSN.Artifact} art
   * @param {object} exts
   */
  function checkPrecisionScaleExtension( art, exts ) {
    if (art.precision && art.scale) {
      if (exts.precision && !exts.scale) {
        error( 'ext-missing-type-property', [ exts.precision.location, exts.precision ],
               { art, prop: 'precision', otherprop: 'scale' } );
      }
    }
  }

  function allowsTypeArgument( art, prop ) {
    const { parameters } = art._effectiveType;
    if (!parameters)
      return false;
    return parameters.includes( prop ) || parameters[0]?.name === prop;
  }

  // Add new members ------------------------------------------------------------

  /**
   * Extend artifact with additional elements and actions: via includes and/or
   * extensions.  This happens _after_ `populateArtifact`, i.e. after eventually
   * having inferred the elements/... from an "origin".
   *
   * `art` can also be a pseudo artifact in `items`.
   */
  function extendArtifactAdd( art ) {
    const { includes, _extensions: extensions } = art;
    if (includes) {
      // propagation of core-compiler relevant annotation assignments:
      propagateEarly( art, '@cds.autoexpose' );
      propagateEarly( art, '@fiori.draft.enabled' );
      reportInvalidIncludes( art );
    }
    else if (!extensions) {     // semantically unnecessary, just for speed-up
      return;
    }
    if (art.items || art.targetAspect || art.returns)
      return;                   // adding enums/elements is pushed down

    const realArt = outerArtifact( art ); // e.g. if `art = realArt.items`

    // params: no new params can be added via extend yet (annotation is ok)
    if (!art.params && extensions?.params &&
        (art.kind === 'action' || art.kind === 'function' ||
         art.kind === 'entity' && art.query))
      art.params = Object.create(null); // for moveDictExtensions()

    // foreign keys: TODO - do something here?

    const { elements } = art;
    if (extensions?.$add) {
      for (const ext of extensions.$add)
        addExtensionEnum( ext, realArt, art );
    }

    if (!elements)    // elements and actions can only added to defs with elements
      return;
    // elements: direct includes + elements → extended includes + elements
    if (includes?.some( i => i._artifact?.elements ) ||
        extensions?.$add?.some( e => e.elements || e.enum )) {
      // TODO: calculate $add here, not in extendArtifactBefore(), consider
      // unreleated layer messages (elements + includes with elements)
      art.elements = Object.create( null );
      art.elements[$location] = elements[$location];
      if (elements[$inferred])
        art.elements[$inferred] = elements[$inferred];
      const def = { elements, includes: includes?.$original || includes };
      const postponeFirst = postponeFirstInclude( def.includes, elements );
      let addedLast = addExtensionMembers( def, realArt, art, 'elements', postponeFirst );
      for (const ext of extensions?.$add || []) {
        const extInclude = ext.includes?.[0];
        if (extInclude) {
          const postpone = extInclude.$postponeInclude ?? 0;
          extInclude.$postponeInclude = postpone + addedLast;
          addedLast = addExtensionMembers( ext, realArt, art, 'elements', postpone );
        }
        else {
          addedLast += addExtensionMembers( ext, realArt, art, 'elements', -1 );
        }
      }
      if (includes)
        reportRedefinitionThroughIncludes( art, 'elements' );
    }

    // actions: via includes (also extended ones) → direct actions → extended actions
    if (art.kind === 'type') {  // TODO: what about event ?
      if (includes)
        reportTypeIncludesWithActions( art );
    }
    else if ((art.kind === 'entity' || art.kind === 'aspect') &&
             (extensions?.actions || includes?.some( ref => ref._artifact?.actions ))) {
      const { actions } = art;
      art.actions = Object.create( null );
      if (actions)
        art.actions[$location] = actions[$location];
      for (const ref of includes || [])
        applyInclude( ref, null, art, 'actions' );
      if (actions)
        addExtensionMembers( { actions }, art, art, 'actions' );
      for (const ext of extensions?.actions || [])
        addExtensionMembers( ext, art, art, 'actions' );
      if (includes)
        reportRedefinitionThroughIncludes( art, 'actions' );
    }
  }

  function addExtensionMembers( ext, art, obj, prop, postpone = -1 ) {
    if (ext.kind)
      dependsOnSilent( art, ext ); // TODO: really do that here?
    if (ext.kind === 'annotate') // is also used for extensions.actions
      return 0;
      // art depends silently on ext (inverse to normal dep!), still necessary?
    const { includes } = ext;
    const extDict = ext[prop];
    if (!extDict && !includes?.some( i => i._artifact?.[prop] ))
      return 0;

    const artDict = obj[prop];
    if (ext.kind &&
        (obj.$inferred || artDict?.[$inferred] || art.query && prop === 'elements') &&
        (extDict || ext.includes))
      reportExtensionOnGenerated( ext, art, prop, extDict );
    let index = 0;
    for (const name in extDict || {}) { // remark: `|| {}` not really necessary
      const adding = extDict[name];
      if (adding.kind === 'annotate' || adding.kind === 'extend')
        continue;
      while (postpone === 0)
        postpone = applyInclude( includes[index++], includes[index], art, prop );
      const existing = artDict[name];
      if (!existing || existing.$inferred === 'include')
        artDict[name] = adding;
      else
        dictAdd( artDict, name, adding, reportDuplicate );
      initMember( adding, art, prop );
      if (!adding.$inferred)    // not for derived members (with aspect include)
        --postpone;             // also when members shadows included one
    }
    if (prop !== 'elements' || !includes?.[index])
      return -1 - postpone;       // number of elements added last (after includes)
    while (index < includes.length)
      applyInclude( includes[index++], null, art, prop );
    return 0;
  }

  function addExtensionEnum( ext, art, obj ) {
    // TODO: test `extend Enum with Include;
    const artDict = obj.enum;
    if (!artDict) {
      if (ext.enum)
        error( 'def-unexpected-enum', [ ext.enum[$location] || ext.name.location, ext ], {} );
      return;
    }
    if (ext.kind)
      dependsOnSilent( art, ext ); // TODO: really do that here?
      // art depends silently on ext (inverse to normal dep!), still necessary?
    const extDict = ext.enum || ext.elements;
    if (!extDict)               // i.e. includes-only extension
      return;
    const notEnum = [];
    if (ext.kind && (art.$inferred || art.query))
      reportExtensionOnGenerated( ext, art, 'enum', extDict );
    for (const name in extDict) {
      const adding = extDict[name];
      if (adding.kind === 'annotate' || adding.kind === 'extend')
        continue;
      if (adding.kind === 'enum' || adding.$syntax === 'or-enum') {
        notEnum.addedAnyway = true;
        adding.kind = 'enum';
        initMember( adding, art, 'enum' );
        dictAdd( artDict, name, adding, reportDuplicate );
      }
      else {
        notEnum.push( name );   // not added to enum dict!
      }
    }
    if (notEnum.length) {
      error( 'ext-unexpected-element', [ extDict[$location], ext ],
             { code: 'extend … with enum', names: notEnum } );
    }
    else if (notEnum.addedAnyway &&
            (!obj.type || obj.type.$inferred || (art._main || art).query)) {
      // TODO: really improve msg id and text
      error( 'extend-type', [ extDict[$location], ext ], {},
             'Only structures or enum types can be extended with elements/enums' );
    }
    else if (!ext.enum) {
      warning( 'ext-expecting-enum', [ extDict[$location], ext ],
               { code: 'extend … with enum' }, 'Use $(CODE) when extending enums' );
    }
  }

  function postponeFirstInclude( includes, members ) {
    if (!includes?.length)
      return -1;
    const postpone = includes[0].$postponeInclude;
    if (postpone != null || !members) // TODO v8: `(postpone !== -1)`
      return postpone ?? 0;
    // compatibility: includes in definition - if elements cover all elements from
    // includes, use provided order - TODO v8: only for CSN input
    for (const ref of includes) {
      const elements = ref._artifact?.elements;
      if (elements && Object.keys( elements ).some( name => !members[name] ))
        return 0;       // some element in some include not covered → normal order
    }
    return -1;                  // includes last = use provided element order
  }

  function applyInclude( ref, nextRef, art, prop ) {
    const include = ref._artifact; // already resolved
    const members = include?.[prop];
    if (!members)
      return nextRef ? nextRef.$postponeInclude ?? 0 : -1;

    // If elements `texts` and `localized` from an included entity are (likely)
    // compiler-generated, users won't expect them to be included:
    const checkForLocalized = prop === 'elements' && include.kind === 'entity' &&
      !include.query && withLocalizedData( include );
    const propagateKeys = art.kind !== 'type' || model.options.v6KeyPropagation;

    for (const name in members) {
      const existing = art[prop][name];
      if (existing && existing.$inferred !== 'include' ||
          checkForLocalized && (name === 'texts' || name === 'localized'))
        continue;   // shadowed by directly defined/extended element, or localized
      const origin = members[name];
      if (origin.$duplicates)   // duplicates are not included
        continue;
      const location = weakRefLocation( ref );
      const proxy = linkToOrigin( origin, name, null, null, location );
      setLink( proxy, '_block', origin._block ); // TODO: why is this necessary?
      proxy.$inferred = 'include';
      if (origin.key && propagateKeys)
        proxy.key = Object.assign( { $inferred: 'include' }, origin.key );
      // TODO: origin.$syntax === 'calc' test?
      if (origin.value && origin.$syntax === 'calc') {
        // TODO: If paths become invalid in the new artifact, should we mark
        //       all usages in the expressions? Possibly just the first one?
        proxy.value = { $inferred: 'include', ...copyExpr( origin.value, location, true ) };
        proxy.$syntax = 'calc';
        createAndLinkCalcDepElement( proxy );
        setLink( proxy, '_calcOrigin', origin._calcOrigin || origin );
      }

      setLink( proxy, '_parent', art );
      setLink( proxy, '_main', art );
      initMember( proxy, art );
      dictAdd( art[prop], name, proxy );
      // delayed reporting of duplicates via reportRedefinitionThroughIncludes()
    }
    return nextRef ? nextRef.$postponeInclude ?? 0 : -1;
  }

  /**
   * Return true if include (with `name` and `elements`) in `ext` highly likely
   * contain elements `texts` and `localized` which are compiler-generated for
   * localized data.  Due to recompilation, we cannot just check the `$inferred`
   * property in the XSN, but need to apply an heuristics.
   * (We could still use $inferred as speed-up if run without `testMode`.)
   *
   * It is as follows: the elements `texts` and `localized` in entity `‹E›` and
   * the entity `‹E›.texts` are considered compiler-generated for Localized Data if
   *
   *  - `‹E›.texts` has a key element `locale`
   *    (TODO: currently weakend to “entity exists”)
   *  - `texts` of `‹E›` is an unmanaged composition to `‹E›.texts`
   *  - `localized` of `‹E›` is an unmanaged association to `‹E›.texts`
   */
  function withLocalizedData( { name, elements } ) { // TODO: use it again
    const textsEntityName = `${ name.id }.texts`;
    // if we test (again) for element `locale` - it might come from an extend or
    // TextsAspect include, which might not have yet applied
    if (!model.definitions[textsEntityName])
      return false;
    const { texts, localized } = elements ?? {};
    return texts?.target && localized?.target && texts.on && localized.on &&
      resolveUncheckedPath( texts.target, 'target', texts ) === textsEntityName &&
      resolveUncheckedPath( localized.target, 'target', localized ) === textsEntityName &&
      resolveUncheckedPath( texts.type, 'type', texts ) === 'cds.Composition' &&
      resolveUncheckedPath( localized.type, 'type', localized ) === 'cds.Association';
  }

  function initMember( member, parent, prop = 'elements' ) {
    if (member._parent === parent) // origin element → nothing to do
      return;
    changeParentLinks( member, parent );
    if (member.targetAspect?.elements)
      setLink( member.targetAspect, '_parent', member._parent );

    if (member.kind === 'action' || member.kind === 'function')
      initBoundSelfParam( member.params, member._main );

    if (parent[prop]?.[$inferred])
      setExpandStatus( parent, 'extend' );

    if (member.$syntax === 'or-enum' && member.value && member.kind === 'element') {
      member.$syntax = 'calc';
      createAndLinkCalcDepElement( member );
    }
  }

  function changeParentLinks( art, parentOrMain ) { // or just `parentOrMain`?
    // TODO: we might also change the implicit name (if name.id is a number,
    // adding the previous column lenght - 1) for better error messages
    if (art._parent?.kind === 'extend')
      setLink( art, '_parent', parentOrMain );
    if (art._outer?.kind === 'extend')
      setLink( art, '_outer', parentOrMain );
    if (art._main?.kind === 'extend')
      setLink( art, '_main', parentOrMain._main || parentOrMain );
    if (art._columnParent?.kind === 'extend')
      art._columnParent = parentOrMain;
    const subColumns = art.expand || art.inline;
    if (subColumns)
      subColumns.forEach( a => changeParentLinks( a, parentOrMain ) );
    forEachMember( initItemsLinks( art, art._block ),
                   a => changeParentLinks( a, parentOrMain ) );
  }

  // Create “super” ANNOTATE statements -----------------------------------------

  /**
   * Create super annotate statements for remaining extensions.
   * Called near the end of the compilation.
   */
  function createRemainingAnnotateStatements() {
    model.extensions = Object.values( model.$collectedExtensions );
    // TODO: testMode sort?
    model.extensions.forEach( createSuperAnnotate );
    // set _artifact links for “main extensions” late as it would disturb the
    // still existing old extend mechanism, see extendArtifactBefore(),
    // needed for LSP and friends:
    Object.values( model.sources ).forEach( setArtifactLinkForExtensions );
    Object.values( model.definitions ).forEach( setArtifactLinkForExtensions );
  }

  function createSuperAnnotate( annotate ) {
    const extensions = annotate._extensions;
    if (extensions && !annotate._main) {
      const art = model.definitions[annotate.name.id];
      for (const ext of extensions)
        reportExtensionOnBuiltin( art, ext ); // induce messages for extension path
      if (art?.builtin && art.kind !== 'namespace') { // TODO: do not set `builtin` on cds, cds.hana
        setLink( annotate, '_extensions', art._extensions ); // for messages and member extensions
        // direct annotations on builtins or on the builtins for propagation, and
        // also shallow-copied to $collectedExtensions for to-csn
        for (const prop in art) {
          if (prop.charAt(0) === '@' || prop === 'doc')
            annotate[prop] = art[prop];
        }
      }
    }
    if (extensions?.length === 1) { // i.e. no proper location if from more than one extension
      annotate.location = extensions[0].location;
      annotate.name.location = extensions[0].name.location;
    }
    extendArtifactBefore( annotate );
    extendArtifactAfter( annotate );
    forEachMember( annotate, createSuperAnnotate );
  }

  // TODO: delete again - if not, what about extensions in contexts/services?
  //       Check test.lsp-api.js! Links in extensions are needed.
  function setArtifactLinkForExtensions( source ) {
    if (!source.extensions)
      return;
    for (const ext of source.extensions) {
      if (!ext.name?.id)
        continue;

      const { name } = ext;
      const { path } = name;
      if (name._artifact === undefined) {
        resolvePath( name, ext.kind, ext ); // induce error & for LSP
      }
      else if (model.options.lspMode && path?.[0]._artifact === undefined) {
        // we don't use resolvePath(…,'extend'), as that would add a dependency
        resolveDefinitionName( ext );
        setArtifactLink( path[path.length - 1], name._artifact );
      }
    }
  }

  function annotateFor( art, prop, name ) {
    const base = annotateBase( art );
    if (name === '' && prop === 'params')
      return base.returns || annotateCreate( base, name, base, 'returns' );
    const dict = base[prop] || (base[prop] = Object.create( null ));
    if (name == null)
      return dict;
    return dict[name] || annotateCreate( dict, name, base );
  }

  function annotateBase( art ) {
    while (art._outer)          // TODO: think about anonymous target aspect
      art = art._outer;
    if (art.kind === 'annotate')
      return art;

    // TODO: more to do if annotate can have `returns` property
    if (art.kind === 'select')
      art = art._parent;
    if (art._main)
      return annotateFor( art._parent, kindProperties[art.kind].dict, art.name.id );

    const { id } = art.name;
    return model.$collectedExtensions[id] ||
           annotateCreate( model.$collectedExtensions, id );
  }

  function annotateCreate( dict, id, parent, prop ) {
    const annotate = {
      __proto__: XsnArtifact.prototype,
      kind: 'annotate',
      name: { __proto__: XsnName.prototype, id, location: genLocation },
      $inferred: '',
      location: genLocation,
    };
    if (parent) {
      setLink( annotate, '_parent', parent );
      setLink( annotate, '_main', parent._main || parent );
    }
    dict[prop || id] = annotate;
    return annotate;
  }

  // Issue messages about dubious extensions ------------------------------------
  // checkXYZ() = return whether to extend, reportXYZ() = extend anyway

  // called from extendArtifactAfter()
  function checkExtensionDictionary( ext, art, artProp, extProp ) {
    if (art.kind === 'annotate') // the super annotate
      return true;
    // assume dict not on art
    const dict = ext[extProp];
    const location = dict?.[$location] ||
      dictFirst( dict )?.name?.location || // for `annotate E:elem`
      ext.name.location;
    switch (artProp) {
      case 'params':
        // currently just via `annotate`, TODO: test w/ CSN input
        warning( 'anno-unexpected-params', [ location, ext ], {},
                 'Parameters only exist for actions or functions' );
        // TODO text: or query entities
        break;
      case 'actions':
        // extendArtifactAdd() had created actions prop with correct actions extensions
        if (ext.kind === 'extend' && Object.keys( dict ).length) {
          error( 'def-unexpected-actions', [ location, ext ], {}, // TODO: ext-
                 'Actions and functions only exist top-level and for entities' ); // or aspects
        }
        else {                  // annotate or empty dict
          warning( 'ext-ignoring-actions', [ location, ext ], {},
                   'Actions and functions only exist top-level and for entities' );
          return true;
        }
        break;
      case 'elements':
        if (ext.kind === 'annotate') {
          warning( 'anno-unexpected-elements', [ location, ext ],
                   { '#': art.type?._artifact?.kind } );
          // extra msg variant for entity as parameter type
        }
        else if (ext.kind === 'extend' && Object.keys( dict ).length) {
          // TODO v8: also error with empty dict
          const msgid = [ 'type', 'aspect' ].includes( art.kind )
            ? 'extend-type'
            : 'def-unexpected-elements';
          error( msgid, [ location, ext ], {} );
        }
        else {                  // annotate or empty dict
          warning( 'ext-ignoring-elements', [ location, ext ], {},
                   'Only structures with directly specified elements can be extended by elements' );
          return true;
        }
        break;
      case 'enum':
        if (ext.kind === 'extend') {
          const msgid = art.kind === 'type' ? 'extend-type' : 'def-unexpected-enum';
          error( msgid, [ location, ext ], {} );
        }
        break;
      case 'foreignKeys': {
        // currently just via `annotate`
        warning( 'ext-undefined-key', [ location, ext ], { '#': 'dict' } );
        break;
      }
      default:
        if (model.options.testMode)
          throw new CompilerAssertion(`Missing case for prop: ${ artProp }`);
    }
    return ext.kind === 'annotate';
    // Remark: to detect security-relevant annotation on (sub) members,
    // super-annotates must be created (→ return true) when no error is reported.
  }

  function reportDuplicate( name, location, art ) {
    if (art.$duplicates)        // already reported in define.js
      return;
    error( 'duplicate-definition', [ art.name.location, art ], {
      name: art.name.id,
      '#': kindProperties[art.kind].normalized || art.kind,
    } );
  }

  function reportUnexpectedMemberExtensions( parent, ext, prop, name ) {
    const securityRelevant = hasSecurityAnno( ext ) ? '-sec' : '';
    const dict = (parent.kind === 'annotate') ? null : parent[prop];
    // real dictionary, not just one in the super-annotate

    // checkExtensionDictionary() had complained about extension with unexpected
    // dict property → new message just for missing art member (or if security
    // relevant)
    if (dict ? dict[name] : !securityRelevant)
      return;

    // Remark: there can currently be just an extend in elements/enum, not actions etc
    switch (prop) {
      case 'elements':
      case 'enum': {
        if (ext.kind === 'annotate' && parent.kind === 'entity' &&
            canBeDraftMember( name, parent, draftElements ))
          break;
        const msgId = (ext.kind === 'extend')
          ? 'extend-undefined'
          : `ext-undefined-element${ securityRelevant }`;
        // eslint-disable-next-line no-nested-ternary
        const msgVn = (!parent._parent?.returns)
          ? prop
          : (prop === 'enum' ? 'enum-returns' : 'returns');
        notFound( msgId, ext.name.location, ext,
                  { '#': msgVn, name, art: parent },
                  dict );
        break;
      }
      case 'foreignKeys': {
        notFound( `ext-undefined-key${ securityRelevant }`, ext.name.location, ext,
                  { name }, parent.foreignKeys );
        break;
      }
      case 'params':
        notFound( `ext-undefined-param${ securityRelevant }`, ext.name.location, ext,
                  { '#': 'param', name },
                  dict );
        break;
      case 'actions':
        if (ext.kind === 'annotate' && parent.kind === 'entity' &&
            canBeDraftMember( name, parent, draftBoundActions ))
          break;
        notFound( `ext-undefined-action${ securityRelevant }`, ext.name.location, ext,
                  { '#': 'action', name },
                  dict );
        break;
      default:
        if (model.options.testMode)
          throw new CompilerAssertion(`Missing case for prop: ${ prop }`);
    }
  }

  /**
   * Complain about invalid `extend service` and `extend context`.
   * Called in extendArtifactBefore().
   */
  function reportInvalidExtensionKind( extensions, art ) {
    for (const ext of extensions) {
      const kind = ext.expectedKind?.val;
      if (kind && kind !== art.kind) {
        const loc = ext.expectedKind.location;
        if (kind === 'context' || kind === 'service') {
          // We have no real artifact during the construction of a super-annotate statement:
          const msgArgs = {
            '#': (art.kind === 'service' || art.kind === 'annotate') ? art.kind : 'std',
            art,
            kind,
            code: 'extend … with definitions',
            keyword: 'extend service',
          };
          // TODO v7: Discuss: make this an error?
          warning( 'ext-invalid-kind', [ loc, ext ], msgArgs, {
            std: 'Artifact $(ART) is not of kind $(KIND), use $(CODE) instead',
            annotate: 'There is no artifact $(ART), use $(CODE) instead',
            // do not mention 'extend context', that is not in CAPire
            service: 'Artifact $(ART) is not of kind $(KIND), use $(CODE) or $(KEYWORD) instead',
          } );
        }
        // TODO: Use similar checks for EXTEND ENTITY etc - 'ext-ignoring-kind'
      }
    }
  }

  // called in createSuperAnnotate()
  function reportExtensionOnBuiltin( art, ext ) {
    const refCtx = extensionRefContext( ext );
    if (resolvePath( ext.name, refCtx, ext ) && art?.builtin) {
      if (ext.kind === 'extend') {
        // extending built-ins with elements/enums already gives an error
        message( 'ext-unexpected-builtin', [ ext.name.location, ext ], {},
                 'Built-in types should not be extended' ); // keep the text general
        // TODO v8: error - especially bad with includes extension
        const typeProp = typeParameters.list.find( p => ext[p] );
        if (typeProp) {
          const location = ext.$typeArgs?.[$location] || ext[typeProp].location;
          message( 'ext-unexpected-type-property', [ location, ext ], {}, // error v7
                   'Built-in types can\'t be extended with type properties' );
          // see also 'ext-invalid-type-property'
        }
      }
      else {
        info( 'anno-builtin', [ ext.name.location, ext ], {} ); // TODO: better location?
      }
      // TODO: remove built-ins as CC candidates via accept property of ./shared.js
    }
  }

  // Called in extendArtifactAdd()
  function reportExtensionOnGenerated( ext, art, prop, extMembers ) {
    // Beware: if we allow element extensions later, we might still want to
    // disallow includes with elements, see reportInvalidIncludes(); additionally,
    // adding sub elements might still be wrong
    const location = ext[prop]?.[$location] || ext.name.location;
    if (ext.enum) {             // enum extension on structure
      error( 'def-unexpected-enum', [ location, ext ], {} );
    }
    else if (art.$inferred === 'include') { // element of include
      error( 'ref-expected-direct-structure', [ location, ext ],
             { '#': 'elements', art } );
    }
    else if (extMembers && Object.keys( extMembers ).length ||
             ext.includes?.some( ref => dictNonEmpty( ref._artifact.elements ))) {
      // TODO: we could allow extMembers containing `extend`s only, but then make
      // sure that we do not accidentially allow adding sub elements
      error( 'extend-for-generated', [ location, ext ],
             {                  // eslint-disable-next-line no-nested-ternary
               '#': (art.query ? 'query' : ext.includes ? 'std' : prop),
               art,
               keyword: 'extend',
             }, {
               std: 'You can\'t use $(KEYWORD) on the generated $(ART)',
               query: 'You can\'t use $(KEYWORD) on the query to add elements',
               elements: 'You can\'t use $(KEYWORD) on the inferred elements of $(ART)',
             } );
      // TODO: for invalid includes, use specific ref-invalid-include messages
    }
  }

  // Remark: the acceptFn for resolvePath() does a first check whether includes
  // are allowed
  function reportInvalidIncludes( art ) {
    const { elements } = art;
    for (const ref of art.includes) {
      const incl = ref._artifact;
      if (!incl)
        continue;
      if (!elements && (incl.elements || incl.kind !== 'aspect'))
        error( 'ref-invalid-include', [ ref.location, art ], { '#': 'bare' } );
      else if ((incl.elements ? incl.elements[$inferred] : incl.kind !== 'aspect') ||
               incl.query)     // TODO: allow query entity and inferred elems soon
        error( 'ref-invalid-include', [ ref.location, art ] );
    }
  }

  // Called in extendArtifactAdd()
  function reportTypeIncludesWithActions( art ) {
    for (const ref of art.includes || []) {
      const incl = ref._artifact;
      if (incl?.actions && Object.keys( incl.actions ).length) {
        warning( 'ref-ignoring-actions', [ ref.location, art ], { art: incl },
                 'The actions of $(ART) are not added to the type' ); // TODO: info?
      }
    }
  }

  // Called in extendArtifactBefore() and extendArtifactAfter()
  function reportUnexpectedReturns( ext, art ) {
    const msgId = hasSecurityAnno( ext.returns )
      ? 'ext-unexpected-returns-sec'
      : 'ext-unexpected-returns';
    message( msgId, [ ext.returns.location, ext ],
             { '#': art.kind, keyword: 'returns' } );
  }

  // Called in extendArtifactAfter()
  function reportMissingReturns( ext, art ) {
    if (ext.kind === 'extend') {
      error( 'ext-unexpected-action', [ ext.name.location, ext ], { '#': art.kind }, {
        std: 'Actions and functions can\'t be extended, only annotated', // TODO: → ext-unsupported
        action: 'Actions can\'t be extended, only annotated',
        function: 'Functions can\'t be extended, only annotated',
      } );
    }
    else {
      warning( 'ext-expecting-returns', [ ext.name.location, ext ], {
        '#': art.kind, keyword: 'returns', code: 'annotate ‹name› with returns { … }',
      }, {
        std: 'Expected $(CODE)', // unused variant
        action: 'Expected $(KEYWORD) when annotating action return structure, i.e. $(CODE)',
        function: 'Expected $(KEYWORD) when annotating function return structure, i.e. $(CODE)',
        // eslint-disable-next-line @stylistic/max-len
        annotate: 'Expected $(KEYWORD) when annotating a return structure of an unknown action or function, i.e. $(CODE)',
      } );
    }
  }

  /**
   * Report duplicates in parent[prop] that happen due to multiple includes having
   * the same member.  Run after includes and extends in extendArtifactAdd() so
   * shadowing members have already replaced any include-derived proxy.
   */
  function reportRedefinitionThroughIncludes( parent, prop ) {
    if (!parent[prop])
      return;
    forEachInOrder( parent, prop, ( member, name ) => {
      if (member.$inferred === 'include' && Array.isArray( member.$duplicates )) {
        const includes = [ member, ...member.$duplicates ].map( dup => dup._origin._main );
        // TODO: 'ref-duplicate-include-member' with one message per affected include,
        // mentioning the problematic element/action names
        error( 'duplicate-definition', [ member.location, member ],
               { '#': `include-${ prop }`, name, sorted_arts: includes } );
      }
    } );
  }

  // TODO: still a bit annotation assignment specific
  // Called in extendArtifactBefore().
  function reportDuplicateExtensions( extensions, prop, issue, index, art ) {
    // TODO: think about messages for these
    if (prop === 'elements' || prop === 'actions' || prop === 'columns' ||
        prop === 'params' || prop === '$add' ) {
      if (issue && (prop === '$add' || prop === 'columns'))
        reportUnstableExtensions( extensions, issue );
      return;                   // extensions currently handled extra
    }

    const isTypeParam = typeParameters.list.includes( prop );
    const isAnnoOrDoc = prop.charAt(0) === '@' || prop === 'doc';
    if (!isAnnoOrDoc && !isTypeParam && prop !== 'orderBy')
      return;
    if (issue) {
      if (prop === 'orderBy' && issue === 'unrelated') {
        for (const ext of extensions) {
          const clause = ext[prop];
          if (clause) {
            message( 'ext-unstable-order', [ clause[0]?.location || ext.location, ext ],
                     { keyword: prop },
                     // eslint-disable-next-line @stylistic/max-len
                     'Unstable order of entries in the $(KEYWORD) clause due to another extension in unrelated layer' );
          }
        }
        return;
      }
      if (isAnnoOrDoc && prop !== 'doc' &&
          allAnnoValuesEqual( extensions, prop )) {
        if (issue === 'unrelated')
          return;
        for (const ext of extensions) {
          const anno = ext[prop];
          if (anno) {
            // annotations with equal value in the same layer -> warn
            warning( 'anno-duplicate-equal', [ anno.name?.location || anno.location, ext ],
                     { '#': 'std', anno: prop, type: art } );
          }
        }
        return;
      }
      // eslint-disable-next-line no-nested-ternary
      let msg = (index < 0)
        ? 'anno-unstable-array'
        : (issue === true)
          ? 'anno-duplicate'
          : 'anno-duplicate-unrelated-layer';
      if (prop === 'includes') {
        msg = (issue === true)
          ? 'ext-duplicate-includes'
          : 'ext-unstable-includes';
        // TODO v7: location on include would be nicer
      }
      else if (!isAnnoOrDoc) {
        msg = (issue === true)
          ? 'ext-duplicate-extend-type'
          : 'ext-duplicate-extend-type-unrelated-layer';
        // not sure whether to repeat the extended artifact in the message (we
        // have the semantic location, after all)
        // extend-repeated-intralayer / extend-unrelated-layer
      }
      const variant = prop === 'doc' ? 'doc' : 'std';
      for (const ext of extensions) {
        const anno = ext[prop];
        if (anno) {
          message( msg, [ anno.name?.location || anno.location, ext ],
                   { '#': variant, anno: prop, type: art } );
        }
      }
    }
    else if (index > 0) {     // more than one set (not just ...)
      const variant = prop === 'doc' ? 'doc' : 'std';
      const msgid = (isAnnoOrDoc)
        ? 'anno-duplicate-same-file' // TODO: always ext-duplicate-…
        : 'ext-duplicate-same-file';
      while (index >= 0) {    // do not report for trailing [...]
        const ext = extensions[index--];
        const anno = ext[prop];
        warning( msgid, [ anno.name?.location || anno.location, ext ],
                 { '#': variant, prop, anno: prop } );
      }
    }
  }

  /**
   * Report 'Warning: Unstable element order due to repeated extensions'
   * except if all extensions are in the same file.
   *
   * Called in extendArtifactBefore(), via reportDuplicateExtensions().
   */
  function reportUnstableExtensions( extensions, issue ) {
    for (const ext of extensions) {
      // TODO: location of complete includes / elements
      // (currently just for having lower diff in tests)
      const location = ext.includes?.[0]?.location ||
        ext.elements && Object.values( ext.elements )[0]?.location ||
        ext.columns?.[0]?.location ||
        ext.location;
      if (issue === 'unrelated') {
        message( 'extend-unrelated-layer', [ location, ext ], {},
                 'Unstable element order due to other extension in unrelated layer' );
      }
      else {
        message( 'extend-repeated-intralayer', [ location, ext ] );
      }
    }
  }

  function allAnnoValuesEqual( extensions, prop ) {
    let first;
    let seen = false;
    for (const ext of extensions) {
      const anno = ext[prop];
      if (anno == null)
        continue;
      if (annotationHasEllipsis( anno ))
        return false;
      if (!seen) {
        first = anno;
        seen = true;
      }
      else if (!annoValueEqual( first, anno )) {
        return false;
      }
    }
    return seen;
  }

  function annoValueEqual( a, b ) {
    if (a == null || b == null)
      return a == null && b == null;
    if (a.literal === 'array' || b.literal === 'array' ||
        a.path || b.path || a.struct || b.struct )
      return false;
    if (a.sym || b.sym) {
      return a.literal === 'enum' && b.literal === 'enum' &&
        a.sym.id === b.sym.id;
    }
    if (!!a.$tokenTexts !== !!b.$tokenTexts)
      return false;
    if (a.$tokenTexts && !('val' in a && 'val' in b))
      return false;
    // no val (undefined) as true for annotation values
    const aVal = ('val' in a) ? a.val : true;
    const bVal = ('val' in b) ? b.val : true;
    const aLit = ('val' in a) ? a.literal : 'boolean';
    const bLit = ('val' in b) ? b.literal : 'boolean';
    return aVal === bVal && aLit === bLit;
  }

  // TODO: in shared?
  function notFound( msgId, location, address, args, validDict ) {
    const msg = message( msgId, [ location, address ], args );
    attachAndEmitValidNames( msg, validDict );
  }

  // Foreign key extensions (currently postponed) -------------------------------

  /**
   * Apply foreign key extensions.  Because foreign keys are handled late in the compiler
   * (in tweak-assocs.js), we can't apply them in effectiveType(), yet.
   * Instead, we postpone applying them until all foreign keys were generated.
   *
   * @param art
   */
  function extendForeignKeys( art ) {
    // See extendArtifactAfter() for targetAspect/items handling.
    if (!art._extensions || art.items || art.targetAspect?.elements)
      return;

    // push down foreign keys
    moveDictExtensions( art, art._extensions, 'foreignKeys', 'elements' );
    if (!art.foreignKeys)
      return;

    forEachGeneric(art, 'foreignKeys', (key) => {
      if (!key._effectiveType)
        throw new CompilerAssertion( 'foreign key should have been processed' );
      extendArtifactBefore( key );
      // Adding foreign key not possible yet
      extendArtifactAfter( key );
    });
  }
}

// Utility functions ------------------------------------------------------------

function canBeDraftMember( name, parent, draftMembers ) {
  return parent?.kind === 'entity' && parent._service && draftMembers.includes( name );
}

/**
 * Group extensions by their layers.  A definition (for specified elements)
 * is considered to be provided in a layer named '', the lowest layer.
 *
 * @param {object[]} extensions Array of extensions.
 * @returns {Record<string, object>} key: layer name, value: {name, layer, extensions[]}`
 */
function layeredExtensions( extensions ) {
  const layered = Object.create( null );
  for (const ext of extensions) {
    const layer = (ext.kind === 'annotate' || ext.kind === 'extend' || ext.kind === 'source') &&
                  layers.layer( ext );
    // just consider layer if Extend/Annotate, not Define
    const name = (layer) ? layer.realname : '';
    const done = layered[name];
    if (done)
      done.extensions.push( ext );
    else
      layered[name] = { name, layer, extensions: [ ext ] };
  }
  return layered;
}

/**
 * Return extensions of the highest layers.
 * Also returns whether there could be an issue:
 * - false: there are just extensions in one file,
 * - 'unrelated': there is just one extension per layer
 * - true: there is at least one layer with two or more extensions, and
 *   at least two files are involved
 *
 * @param {Record<string, object>} layered Structure as returned by layeredExtensions()
 * @returns {{highest, issue: boolean|string}}
 */
function extensionsOfHighestLayers( layered ) {
  const layerNames = Object.keys( layered );
  // console.log('HIB:',layerNames)
  if (layerNames.length <= 1) {
    const name = layerNames[0];
    const highest = layered[name]?.extensions || [];
    highest.sort( compareExtensions );
    delete layered[name];
    return { highest, issue: inMoreThanOneFile( highest ) };
  }

  // collect all layers which are lower than another layer
  const allExtends = Object.create( null );
  allExtends[''] = {};        // the "Define" layer
  for (const name of layerNames) {
    if (name)                 // not the "Define" layer
      Object.assign( allExtends, layered[name].layer._layerExtends );
  }
  // console.log('HIE:',Object.keys(allExtends))
  const highest = [];           // extensions
  const highestLayers = [];
  for (const name of layerNames) {
    if (!(name in allExtends)) {
      const layer = layered[name];
      delete layered[name];
      highestLayers.push( layer );
      highest.push( ...layer.extensions );
    }
  }
  highest.sort( compareExtensions );
  const good = highestLayers.every( layer => !inMoreThanOneFile( layer.extensions ) );
  // TODO: use layer.file instead
  const issue = !good || highestLayers.length > 1 && 'unrelated';
  // console.log('HI:',highest.map(l=>l.name),issue,issue&&extensions)
  return { highest, issue };
}

function inMoreThanOneFile( extensions ) {
  if (extensions.length <= 1)
    return false;
  const file = extensions[0].location?.file;
  return !file || extensions.some( e => e.location?.file !== file );
}

/**
 * Compare two extensions which are not comparable via layering:
 * - via the fs.realpath of the file (not layer!) of the extensions, then
 * - via the line, then column of the extensions.
 * Returns <0 if `a`<`b`, >1 if `a`>`b`, i.e. can be used for ascending sort.
 */
function compareExtensions( a, b ) {
  const fileA = layers.realname( a );
  const fileB = layers.realname( b );
  if (fileA !== fileB)
    return (fileA > fileB) ? 1 : -1;
  return (a?.location?.line || 0) - (b?.location?.line || 0) ||
    (a?.location?.col || 0) - (b?.location?.col || 0);
}


/**
 * Propagate the given `prop` (e.g. annotation) early, i.e. copy it from all `.includes`
 * if they have the property.
 * TODO: move to ./utils.js,
 *
 * @param {XSN.Definition} art
 * @param {string} prop
 */
function propagateEarly( art, prop ) {
  if (art[prop])
    return;
  for (const ref of art.includes) {
    const aspect = ref._artifact;
    if (aspect) {
      const anno = aspect[prop];
      if (anno && (anno.val !== null || !art[prop]))
        art[prop] = Object.assign( { $inferred: 'include' }, anno );
    }
  }
}

function pushTo$add( extensions, ext ) {
  if (!extensions.$add)
    extensions.$add = [ ext ];
  else if (extensions.$add.at( -1 ) !== ext)
    extensions.$add.push( ext );
}

module.exports = extend;
